const logoData = "";
const logoPoints = 20000;
const logoAspect = 0.65540000;
const logoWidth = addControl("iconWidth", "Weekend Icon Static Float Width", 162, 540, 360);
const drift = addControl("iconDrift", "Soft Drift", 0, 18, 4.5);
const tempo = addControl("iconTempo", "Drift Tempo", 0.1, 2.0, 0.65);
const depth = addControl("iconDepth", "Soft Depth", 0, 40, 5.5);
const t = time * tempo;
const id = i + 1;
const k = (i % logoPoints) * 6;
let c0 = logoData.charCodeAt(k);
let c1 = logoData.charCodeAt(k + 1);
let c2 = logoData.charCodeAt(k + 2);
let c3 = logoData.charCodeAt(k + 3);
let c4 = logoData.charCodeAt(k + 4);
let c5 = logoData.charCodeAt(k + 5);
c0 = c0 > 64 ? c0 - 55 : c0 - 48;
c1 = c1 > 64 ? c1 - 55 : c1 - 48;
c2 = c2 > 64 ? c2 - 55 : c2 - 48;
c3 = c3 > 64 ? c3 - 55 : c3 - 48;
c4 = c4 > 64 ? c4 - 55 : c4 - 48;
c5 = c5 > 64 ? c5 - 55 : c5 - 48;
const qx = c0 * 256 + c1 * 16 + c2;
const qy = c3 * 256 + c4 * 16 + c5;
const lx = (qx / 4095 - 0.5) * logoWidth;
const ly = (0.5 - qy / 4095) * logoWidth * logoAspect;
let h = Math.sin(id * 12.9898) * 43758.5453;
h = h - Math.floor(h);
let h2 = Math.sin(id * 78.233) * 19341.113;
h2 = h2 - Math.floor(h2);
let h3 = Math.sin(id * 37.719) * 9517.721;
h3 = h3 - Math.floor(h3);
const a = t * 1.17 + h * 6.28318530718;
const b = t * 0.73 + h2 * 6.28318530718;
const local = drift * (0.32 + h3 * 0.68);
const px = lx + Math.sin(a) * local;
const py = ly + Math.cos(b) * local * 0.72;
const pz = Math.sin(a * 0.61 + b * 0.39) * depth * (0.25 + h2 * 0.75);
target.set(px, py, pz);
color.setHSL(0.105 + h2 * 0.035, 0.24 + h3 * 0.08, 0.86 + Math.sin(t * 1.3 + h * 6.28318530718) * 0.035);
if (i === 0) setInfo("Weekend Icon Static Float", "Already formed vector map with only small local drift.");